NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: "vam ghaH the Revelation vo' Jesus Christ, nuq joH'a' nobta' ghaH Daq cha' Daq Daj toy'wI'pu' the Dochmey nuq must qaS soon, nuq ghaH ngeHta' je chenmoHta' Sovta' Sum Daj Duy { Note: joq, messenger (naDev je wherever Duy ghaH mentioned) } Daq Daj toy'wI', John,",
        2: "'Iv testified Daq joH'a' mu', je vo' the testimony vo' Jesus Christ, about everything vetlh ghaH leghta'.",
        3: "ghurtaH ghaH ghaH 'Iv reads je chaH 'Iv Qoy the mu'mey vo' the prophecy, je pol the Dochmey vetlh 'oH ghItlhta' Daq 'oH, vaD the poH ghaH Daq ghop.",
        4: "John, Daq the Soch yejmey vetlh 'oH Daq Asia: Grace Daq SoH je roj, vo' joH'a', 'Iv ghaH je 'Iv ghaHta' je 'Iv ghaH Daq ghoS; je vo' the Soch Spirits 'Iv 'oH qaSpa' Daj quS'a';",
        5: "je vo' Jesus Christ, the voqmoH witness, the firstborn vo' the Heghpu', je the ruler vo' the joHpu' vo' the tera'. Daq ghaH 'Iv muSHa'taH maH, je washed maH vo' maj yemmey Sum Daj 'Iw;",
        6: "je ghaH chenmoHta' maH Daq taH a Kingdom, lalDan vumwI'pu' { Note: Exodus 19:6; Isaiah 61:6 } Daq Daj joH'a' je vav; Daq ghaH taH the batlh je the dominion reH je ever. Amen.",
        7: "yIlegh, ghaH ghaH choltaH tlhej the clouds, je Hoch mIn DichDaq legh ghaH, including chaH 'Iv pierced ghaH. Hoch the tuqpu' vo' the tera' DichDaq mourn Dung ghaH. 'ach vaj, Amen.",
        8: "“jIH 'oH the Alpha je the Omega, { Note: TR cheltaH “the tagh je the pItlh” }” jatlhtaH the joH joH'a', { Note: TR omits “joH'a'” } “'Iv ghaH je 'Iv ghaHta' je 'Iv ghaH Daq ghoS, the HoSghaj.”",
        9: "jIH John, lIj loDnI' je partner tlhej SoH Daq oppression, Kingdom, je perseverance Daq Christ Jesus, ghaHta' Daq the isle vetlh ghaH ja' Patmos because vo' joH'a' mu' je the testimony vo' Jesus Christ.",
        10: "jIH ghaHta' Daq the qa' Daq the joH jaj, je jIH Qoyta' behind jIH a loud ghogh, rur a trumpet",
        11: "ja'ta', “{ Note: TR cheltaH “jIH 'oH the Alpha je the Omega, the wa'Dich je the Last.” } nuq SoH legh, write Daq a paq je ngeH Daq the Soch yejmey { Note: TR cheltaH “nuq 'oH Daq Asia” }: Daq Ephesus, Smyrna, Pergamum, Thyatira, Sardis, Philadelphia, je Daq Laodicea.”",
        12: "jIH tlhe'ta' Daq legh the ghogh vetlh jatlhta' tlhej jIH. ghajtaH tlhe'ta', jIH leghta' Soch golden lampstands.",
        13: "je among the lampstands ghaHta' wa' rur a puqloD vo' loD, { Note: Daniel 7:13 } clothed tlhej a robe reaching bIng Daq Daj qamDu', je tlhej a golden sash around Daj chest.",
        14: "Daj nach je Daj jIb were chIS as chIS wool, rur chuchHommey. Daj mInDu' were rur a flame vo' qul.",
        15: "Daj qamDu' were rur burnished brass, as chugh 'oH ghajta' taH refined Daq a furnace. Daj ghogh ghaHta' rur the ghogh vo' law' bIQmey.",
        16: "ghaH ghajta' Soch stars Daq Daj nIH ghop. pa' vo' Daj nujDu' proceeded a sharp cha'-edged 'etlh. Daj qab ghaHta' rur the pemHov shining Daq its brightest.",
        17: "ghorgh jIH leghta' ghaH, jIH pumta' Daq Daj qamDu' rur a Heghpu' loD. ghaH laid Daj nIH ghop Daq jIH, ja'ta', “yImev taH vIp. jIH 'oH the wa'Dich je the last,",
        18: "je the yIntaH wa'. jIH ghaHta' Heghpu', je yIlegh, jIH 'oH yIn forevermore. Amen. jIH ghaj the keys vo' Hegh je vo' Hades { Note: joq, Hell }.",
        19: "Write vaj the Dochmey nuq SoH ghaj leghpu', je the Dochmey nuq 'oH, je the Dochmey nuq DichDaq qaS hereafter;",
        20: "the mystery vo' the Soch stars nuq SoH leghta' Daq wIj nIH ghop, je the Soch golden lampstands. The Soch stars 'oH the Duy''a'pu' { Note: joq, Duypu' (naDev je wherever Duy''a'pu' 'oH mentioned) } vo' the Soch yejmey. The Soch lampstands 'oH Soch yejmey.",
    },
    2: {
        1: "“Daq the Duy vo' the yej Daq Ephesus write: “ghaH 'Iv holds the Soch stars Daq Daj nIH ghop, ghaH 'Iv yIttaH among the Soch golden lampstands jatlhtaH Dochvammey Dochmey:",
        2: "“jIH Sov lIj vum, je lIj toil je perseverance, je vetlh SoH ta'laHbe' tolerate mIghtaHghach loDpu', je ghaj tested chaH 'Iv ja' themselves apostles, je chaH 'oH ghobe', je tu'ta' chaH false.",
        3: "SoH ghaj perseverance je ghaj endured vaD wIj pong chIch, je ghaj { Note: TR cheltaH “ghaj labored je” } ghobe' grown Doy'.",
        4: "'ach jIH ghaj vam Daq SoH, vetlh SoH poS lIj wa'Dich muSHa'.",
        5: "qaw vaj vo' nuqDaq SoH ghaj fallen, je repent je ta' the wa'Dich vum; joq else jIH 'oH choltaH Daq SoH swiftly, je DichDaq vIH lIj lampstand pa' vo' its Daq, unless SoH repent.",
        6: "'ach vam SoH ghaj, vetlh SoH hate the vum vo' the Nicolaitans, nuq jIH je hate.",
        7: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey. Daq ghaH 'Iv overcomes jIH DichDaq nob Daq Sop vo' the Sor vo' yIn, nuq ghaH Daq the Paradise vo' wIj joH'a'.",
        8: "“Daq the Duy vo' the yej Daq Smyrna write: “The wa'Dich je the last, 'Iv ghaHta' Heghpu', je ghajtaH ghoS Daq yIn jatlhtaH Dochvammey Dochmey:",
        9: "“jIH Sov lIj vum, oppression, je lIj poverty ('ach SoH 'oH rich), je the blasphemy vo' chaH 'Iv jatlh chaH 'oH Jews, je chaH 'oH ghobe', 'ach 'oH a synagogue vo' Satan.",
        10: "yImev taH vIp vo' the Dochmey nuq SoH 'oH about Daq suffer. yIlegh, the devil ghaH about Daq throw 'op vo' SoH Daq prison, vetlh SoH may taH tested; je SoH DichDaq ghaj oppression vaD wa'maH jajmey. taH voqmoH Daq Hegh, je jIH DichDaq nob SoH the crown vo' yIn.",
        11: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey. ghaH 'Iv overcomes won't taH harmed Sum the cha'DIch Hegh.",
        12: "“Daq the Duy vo' the yej Daq Pergamum write: “ghaH 'Iv ghajtaH the sharp cha'-edged 'etlh jatlhtaH Dochvammey Dochmey:",
        13: "“jIH Sov lIj vum je nuqDaq SoH yIn, nuqDaq Satan's quS'a' ghaH. SoH 'uch firmly Daq wIj pong, je ta'be' deny wIj HartaHghach Daq the jajmey vo' Antipas wIj witness, wIj voqmoH wa', 'Iv ghaHta' HoHta' among SoH, nuqDaq Satan yIntaH.",
        14: "'ach jIH ghaj a few Dochmey Daq SoH, because SoH ghaj pa' 'op 'Iv 'uch the teaching vo' Balaam, 'Iv taught Balak Daq throw a stumbling block qaSpa' the puqpu' vo' Israel, Daq Sop Dochmey sacrificed Daq idols, je Daq commit sexual immorality.",
        15: "vaj SoH je ghaj 'op 'Iv 'uch Daq the teaching vo' the Nicolaitans likewise { Note: TR reads “nuq jIH hate” instead vo' “likewise” }.",
        16: "Repent vaj, joq else jIH 'oH choltaH Daq SoH quickly, je jIH DichDaq chenmoH veS Daq chaH tlhej the 'etlh vo' wIj nujDu'.",
        17: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey. Daq ghaH 'Iv overcomes, Daq ghaH jIH DichDaq nob vo' the hidden manna, { Note: Manna ghaH supernatural Soj, named after the Hebrew vaD “nuq ghaH 'oH?”. legh Exodus 11:7-9. } je jIH DichDaq nob ghaH a chIS nagh, je Daq the nagh a chu' pong ghItlhta', nuq ghobe' wa' SovtaH 'ach ghaH 'Iv receives 'oH.",
        18: "“Daq the Duy vo' the yej Daq Thyatira write: “The puqloD vo' joH'a', 'Iv ghajtaH Daj mInDu' rur a flame vo' qul, je Daj qamDu' 'oH rur burnished brass, jatlhtaH Dochvammey Dochmey:",
        19: "“jIH Sov lIj vum, lIj muSHa', HartaHghach, toy'taHghach, patient endurance, je vetlh lIj last vum 'oH latlh than the wa'Dich.",
        20: "'ach jIH ghaj vam Daq SoH, vetlh SoH tolerate lIj { Note: TR, NU read “vetlh” instead vo' “lIj” } be', Jezebel, 'Iv calls herself a prophetess. ghaH teaches je seduces wIj toy'wI'pu' Daq commit sexual immorality, je Daq Sop Dochmey sacrificed Daq idols.",
        21: "jIH nobta' Daj poH Daq repent, 'ach ghaH refuses Daq repent vo' Daj sexual immorality.",
        22: "yIlegh, jIH DichDaq throw Daj Daq a bed, je chaH 'Iv commit voqHa'moHlu' tlhej Daj Daq Dun oppression, unless chaH repent vo' Daj vum.",
        23: "jIH DichDaq HoH Daj puqpu' tlhej Hegh, je Hoch the yejmey DichDaq Sov vetlh jIH 'oH ghaH 'Iv searches the minds je tIQDu'. jIH DichDaq nob Daq each wa' vo' SoH according Daq lIj deeds.",
        24: "'ach Daq SoH jIH jatlh, Daq the leS 'Iv 'oH Daq Thyatira, as law' as yImev ghaj vam teaching, 'Iv yImev Sov nuq 'op ja' ‘the deep Dochmey vo' Satan,' Daq SoH jIH jatlh, jIH 'oH ghobe' putting vay' latlh burden Daq SoH.",
        25: "Nevertheless, 'uch vetlh nuq SoH ghaj firmly until jIH ghoS.",
        26: "ghaH 'Iv overcomes, je ghaH 'Iv keeps wIj vum Daq the pItlh, Daq ghaH jIH DichDaq nob authority Dung the tuqpu'.",
        27: "ghaH DichDaq rule chaH tlhej a DevwI' naQ vo' iron, shattering chaH rur clay pots; { Note: bom 2:9 } as jIH je ghaj Hevta' vo' wIj vav:",
        28: 'je jIH DichDaq nob ghaH the po Hov.',
        29: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey.",
    },
    3: {
        1: "“je Daq the Duy vo' the yej Daq Sardis write: “ghaH 'Iv ghajtaH the Soch Spirits vo' joH'a', je the Soch stars jatlhtaH Dochvammey Dochmey: “jIH Sov lIj vum, vetlh SoH ghaj a reputation vo' taH yIn, 'ach SoH 'oH Heghpu'.",
        2: "Wake Dung, je pol the Dochmey vetlh remain, nuq SoH were about Daq throw DoH, vaD jIH ghaj tu'ta' ghobe' vum vo' yours perfected qaSpa' wIj joH'a'.",
        3: "qaw vaj chay' SoH ghaj Hevta' je Qoyta'. pol 'oH, je repent. chugh vaj SoH won't watch, jIH DichDaq ghoS as a thief, je SoH won't Sov nuq hour jIH DichDaq ghoS upon SoH.",
        4: "Nevertheless SoH ghaj a few pongmey Daq Sardis vetlh ta'ta' ghobe' defile chaj garments. chaH DichDaq yIt tlhej jIH Daq chIS, vaD chaH 'oH worthy.",
        5: "ghaH 'Iv overcomes DichDaq taH arrayed Daq chIS garments, je jIH DichDaq Daq ghobe' way blot Daj pong pa' vo' the paq vo' yIn, je jIH DichDaq confess Daj pong qaSpa' wIj vav, je qaSpa' Daj Duy''a'pu'.",
        6: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey.",
        7: "“Daq the Duy vo' the yej Daq Philadelphia write: “ghaH 'Iv ghaH le', ghaH 'Iv ghaH true, ghaH 'Iv ghajtaH the key vo' David, ghaH 'Iv opens je ghobe' wa' laH shut, je 'Iv shuts je ghobe' wa' opens, jatlhtaH Dochvammey Dochmey:",
        8: "“jIH Sov lIj vum (yIlegh, jIH ghaj cher qaSpa' SoH an poSmoH lojmIt, nuq ghobe' wa' laH shut), vetlh SoH ghaj a mach HoS, je polta' wIj mu', je ta'be' deny wIj pong.",
        9: "yIlegh, jIH nob vo' the synagogue vo' Satan, vo' chaH 'Iv jatlh chaH 'oH Jews, je chaH 'oH ghobe', 'ach Qot. yIlegh, jIH DichDaq chenmoH chaH Daq ghoS je lalDan toy' qaSpa' lIj qamDu', je Daq Sov vetlh jIH ghaj loved SoH.",
        10: "Because SoH polta' wIj ra'ta'ghach mu'mey Daq SIQ, jIH je DichDaq pol SoH vo' the hour vo' testing, nuq ghaH Daq ghoS Daq the Hoch qo', Daq test chaH 'Iv yIn Daq the tera'.",
        11: "jIH 'oH choltaH quickly! 'uch firmly vetlh nuq SoH ghaj, vaj vetlh ghobe' wa' takes lIj crown.",
        12: "ghaH 'Iv overcomes, jIH DichDaq chenmoH ghaH a pillar Daq the lalDan qach vo' wIj joH'a', je ghaH DichDaq jaH pa' vo' pa' ghobe' latlh. jIH DichDaq write Daq ghaH the pong vo' wIj joH'a', je the pong vo' the veng vo' wIj joH'a', the chu' Jerusalem, nuq choltaH bIng pa' vo' chal vo' wIj joH'a', je wIj ghaj chu' pong.",
        13: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey.",
        14: "“Daq the Duy vo' the yej Daq Laodicea write: “The Amen, the voqmoH je True Witness, the nach vo' joH'a' creation, jatlhtaH Dochvammey Dochmey:",
        15: "“jIH Sov lIj vum, vetlh SoH 'oH ghobe' cold ghobe' hot. jIH wish SoH were cold joq hot.",
        16: "vaj, because SoH 'oH lukewarm, je ghobe' hot ghobe' cold, jIH DichDaq vomit SoH pa' vo' wIj nujDu'.",
        17: "Because SoH jatlh, ‘jIH 'oH rich, je ghaj gotten riches, je ghaj need vo' pagh;' je yImev Sov vetlh SoH 'oH the wretched wa', miserable, mIpHa', blind, je naked;",
        18: "jIH qeS SoH Daq buy vo' jIH SuD baS refined Sum qul, vetlh SoH may moj rich; je chIS garments, vetlh SoH may clothe SoH'egh, je vetlh the tuH vo' lIj nakedness may ghobe' taH 'angta'; je mIn salve Daq anoint lIj mInDu', vetlh SoH may legh.",
        19: "As law' as jIH muSHa', jIH reprove je chasten. taH zealous vaj, je repent.",
        20: 'yIlegh, jIH Qam Daq the lojmIt je knock. chugh anyone hears wIj ghogh je opens the lojmIt, vaj jIH DichDaq ghoS Daq Daq ghaH, je DichDaq dine tlhej ghaH, je ghaH tlhej jIH.',
        21: "ghaH 'Iv overcomes, jIH DichDaq nob Daq ghaH Daq ba' bIng tlhej jIH Daq wIj quS'a', as jIH je overcame, je ba'ta' bIng tlhej wIj vav Daq Daj quS'a'.",
        22: "ghaH 'Iv ghajtaH an qogh, chaw' ghaH Qoy nuq the qa' jatlhtaH Daq the yejmey.”",
    },
    4: {
        1: "After Dochvammey Dochmey jIH nejta' je leghta' a lojmIt poSmaHpu' Daq chal, je the wa'Dich ghogh vetlh jIH Qoyta', rur a trumpet speaking tlhej jIH, ghaHta' wa' ja'ta', “ghoS Dung naDev, je jIH DichDaq cha' SoH the Dochmey nuq must qaS after vam.”",
        2: "SibI' jIH ghaHta' Daq the qa'. yIlegh, pa' ghaHta' a quS'a' cher Daq chal, je wa' sitting Daq the quS'a'",
        3: "vetlh nejta' rur a jasper nagh je a sardius. pa' ghaHta' a rainbow around the quS'a', rur an emerald Daq legh Daq.",
        4: "Around the quS'a' were cha'maH- loS thrones. Daq the thrones were cha'maH- loS quppu' sitting, dressed Daq chIS garments, tlhej crowns vo' SuD baS Daq chaj nachDu'.",
        5: "pa' vo' the quS'a' proceed lightnings, wabmey, je thunders. pa' were Soch lamps vo' qul burning qaSpa' Daj quS'a', nuq 'oH the Soch Spirits vo' joH'a'.",
        6: "qaSpa' the quS'a' ghaHta' something rur a biQ'a' vo' glass, rur Daq crystal. Daq the midst vo' the quS'a', je around the quS'a' were loS yIntaH creatures teblu'ta' vo' mInDu' qaSpa' je behind.",
        7: "The wa'Dich creature ghaHta' rur a HaDI'baH, je the cha'DIch creature rur a calf, je the wejDIch creature ghajta' a qab rur a loD, je the fourth ghaHta' rur a flying eagle.",
        8: "The loS yIntaH creatures, each wa' vo' chaH ghajtaH jav telDu', 'oH teblu'ta' vo' mInDu' around je within. chaH ghaj ghobe' leS jaj je ram, ja'ta', “le', le', le' { Note: Hodges/Farstad MT reads “le'” 9 poHmey instead vo' 3. } ghaH the joH joH'a', the HoSghaj, 'Iv ghaHta' je 'Iv ghaH je 'Iv ghaH Daq ghoS!”",
        9: "ghorgh the yIntaH creatures nob batlh, quv, je tlho' Daq ghaH 'Iv sits Daq the quS'a', Daq ghaH 'Iv yIn reH je ever,",
        10: "the cha'maH- loS quppu' pum bIng qaSpa' ghaH 'Iv sits Daq the quS'a', je lalDan toy' ghaH 'Iv yIn reH je ever, je throw chaj crowns qaSpa' the quS'a', ja'ta',",
        11: "“Worthy 'oH SoH, maj joH je joH'a', the le' wa', { Note: TR omits “je joH'a', the le' wa',” } Daq Hev the batlh, the quv, je the HoS, vaD SoH created Hoch Dochmey, je because vo' lIj neH chaH existed, je were created!”",
    },
    5: {
        1: "jIH leghta', Daq the nIH ghop vo' ghaH 'Iv ba'ta' Daq the quS'a', a paq ghItlhta' inside je outside, sealed shut tlhej Soch seals.",
        2: "jIH leghta' a HoS Duy proclaiming tlhej a loud ghogh, “'Iv ghaH worthy Daq poSmoH the paq, je Daq ghor its seals?”",
        3: "ghobe' wa' Daq chal Dung, joq Daq the tera', joq bIng the tera', ghaHta' laH Daq poSmoH the paq, joq Daq legh Daq 'oH.",
        4: "je jIH wept 'ar, because ghobe' wa' ghaHta' tu'ta' worthy Daq poSmoH the paq, joq Daq legh Daq 'oH.",
        5: "wa' vo' the quppu' ja'ta' Daq jIH, “yImev weep. yIlegh, the HaDI'baH 'Iv ghaH vo' the tuq vo' Judah, the Root vo' David, ghajtaH overcome; ghaH 'Iv opens the paq je its Soch seals.”",
        6: "jIH leghta' Daq the midst vo' the quS'a' je vo' the loS yIntaH creatures, je Daq the midst vo' the quppu', a Lamb standing, as 'a' 'oH ghajta' taH Heghta', ghajtaH Soch horns, je Soch mInDu', nuq 'oH the Soch Spirits vo' joH'a', ngeHta' pa' Daq Hoch the tera'.",
        7: "vaj ghaH ghoSta', je ghaH tlhapta' 'oH pa' vo' the nIH ghop vo' ghaH 'Iv ba'ta' Daq the quS'a'.",
        8: "DaH ghorgh ghaH ghajta' tlhappu' the paq, the loS yIntaH creatures je the cha'maH- loS quppu' pumta' bIng qaSpa' the Lamb, each wa' ghajtaH a harp, je golden bowls teblu'ta' vo' He', nuq 'oH the qoy'taHghachmey vo' the le' ghotpu'.",
        9: "chaH bomta' a chu' bom, ja'ta', “SoH 'oH worthy Daq tlhap the paq, je Daq poSmoH its seals: vaD SoH were HoHta', je je'ta' maH vaD joH'a' tlhej lIj 'Iw, pa' vo' Hoch tuq, language, ghotpu, je Hatlh,",
        10: "je chenmoHta' maH joHpu' je lalDan vumwI'pu' Daq maj joH'a', je maH DichDaq che' Daq tera'.”",
        11: "jIH leghta', je jIH Qoyta' something rur a ghogh vo' law' Duy''a'pu' around the quS'a', the yIntaH creatures, je the quppu'; je the mI' vo' chaH ghaHta' wa'maH SaDmey vo' wa'maH SaDmey, je SaDmey vo' SaDmey;",
        12: "ja'ta' tlhej a loud ghogh, “Worthy ghaH the Lamb 'Iv ghajtaH taH HoHta' Daq Hev the HoS, wealth, valtaHghach, HoS, quv, batlh, je blessing!”",
        13: "jIH Qoyta' Hoch created Doch nuq ghaH Daq chal, Daq the tera', bIng the tera', Daq the biQ'a', je everything Daq chaH, ja'ta', “Daq ghaH 'Iv sits Daq the quS'a', je Daq the Lamb taH the blessing, the quv, the batlh, je the dominion, reH je ever! Amen! { Note: TR omits “Amen!” }”",
        14: "The loS yIntaH creatures ja'ta', “Amen!” The { Note: TR cheltaH “cha'maH- loS” } quppu' pumta' bIng je worshiped. { Note: TR cheltaH “the wa' yIntaH reH je ever” }",
    },
    6: {
        1: "jIH leghta' vetlh the Lamb poSmaHpu' wa' vo' the Soch seals, je jIH Qoyta' wa' vo' the loS yIntaH creatures ja'ta', as tlhej a ghogh vo' thunder, “ghoS je legh!”",
        2: "je yIlegh, a chIS horse, je ghaH 'Iv ba'ta' Daq 'oH ghajta' a bow. A crown ghaHta' nobpu' Daq ghaH, je ghaH ghoSta' vo' conquering, je Daq chargh.",
        3: "ghorgh ghaH poSmaHpu' the cha'DIch seal, jIH Qoyta' the cha'DIch yIntaH creature ja'ta', “ghoS!”",
        4: "Another ghoSta' vo', a Doq horse. Daq ghaH 'Iv ba'ta' Daq 'oH ghaHta' nobpu' HoS Daq tlhap roj vo' the tera', je vetlh chaH should HoH wa' another. pa' ghaHta' nobpu' Daq ghaH a Dun 'etlh.",
        5: "ghorgh ghaH poSmaHpu' the wejDIch seal, jIH Qoyta' the wejDIch yIntaH creature ja'ta', “ghoS je legh!” je yIlegh, a black horse, je ghaH 'Iv ba'ta' Daq 'oH ghajta' a 'ughghach juvwI' Daq Daj ghop.",
        6: "jIH Qoyta' a ghogh Daq the midst vo' the loS yIntaH creatures ja'ta', “A choenix { Note: A choenix ghaH a dry volume juv vetlh ghaH a mach latlh than a litre (a mach latlh than a quart). } vo' wheat vaD a denarius, je wej choenix vo' barley vaD a denarius! yImev damage the Hergh je the HIq!”",
        7: "ghorgh ghaH poSmaHpu' the fourth seal, jIH Qoyta' the fourth yIntaH creature ja'ta', “ghoS je legh!”",
        8: "je yIlegh, a pale horse, je ghaH 'Iv ba'ta' Daq 'oH, Daj pong ghaHta' Hegh. Hades { Note: joq, Hell } tlha'ta' tlhej ghaH. Authority Dung wa' fourth vo' the tera', Daq HoH tlhej the 'etlh, tlhej famine, tlhej Hegh, je Sum the wild Ha'DIbaH vo' the tera' ghaHta' nobpu' Daq ghaH.",
        9: "ghorgh ghaH poSmaHpu' the fifth seal, jIH leghta' underneath the lalDanta' Daq the qa'pu' vo' chaH 'Iv ghajta' taH HoHta' vaD the mu' vo' joH'a', je vaD the testimony vo' the Lamb nuq chaH ghajta'.",
        10: "chaH SaQta' tlhej a loud ghogh, ja'ta', “chay' tIq, pIn, the le' je true, until SoH noH je bortaS maj 'Iw Daq chaH 'Iv yIn Daq the tera'?”",
        11: "A tIq chIS robe ghaHta' nobpu' Daq each vo' chaH. chaH were ja'ta' vetlh chaH should leS yet vaD a qaStaHvIS, until chaj fellow toy'wI'pu' je chaj loDnI'pu', { Note: The mu' vaD “loDnI'pu'” naDev je nuqDaq context allows may je taH correctly translated “loDnI'pu' je sisters” joq “siblings.” } 'Iv would je taH HoHta' 'ach as chaH were, should complete chaj course.",
        12: "jIH leghta' ghorgh ghaH poSmaHpu' the javDich seal, je pa' ghaHta' a Dun earthquake. The pemHov mojta' black as sackcloth chenmoHta' vo' jIb, je the Hoch maS mojta' as 'Iw.",
        13: "The stars vo' the sky pumta' Daq the tera', rur a fig Sor dropping its unripe figs ghorgh 'oH ghaH shaken Sum a Dun SuS.",
        14: "The sky ghaHta' teqta' rur a scroll ghorgh 'oH ghaH rolled Dung. Hoch HuD je island were vIHta' pa' vo' chaj Daqmey.",
        15: "The joHpu' vo' the tera', the joHHom, the commanding officers, the rich, the HoS, je Hoch toy'wI''a' je free person, hid themselves Daq the caves je Daq the rocks vo' the Hudmey.",
        16: "chaH ja'ta' the Hudmey je the rocks, “pum Daq maH, je So' maH vo' the qab vo' ghaH 'Iv sits Daq the quS'a', je vo' the QeHpu' vo' the Lamb,",
        17: "vaD the Dun jaj vo' Daj QeHpu' ghajtaH ghoS; je 'Iv ghaH laH Daq Qam?”",
    },
    7: {
        1: "After vam, jIH leghta' loS Duy''a'pu' standing Daq the loS corners vo' the tera', holding the loS winds vo' the tera', vaj vetlh ghobe' SuS would blow Daq the tera', joq Daq the biQ'a', joq Daq vay' Sor.",
        2: "jIH leghta' another Duy ascend vo' the sunrise, ghajtaH the seal vo' the yIntaH joH'a'. ghaH SaQta' tlhej a loud ghogh Daq the loS Duy''a'pu' Daq 'Iv 'oH ghaHta' nobpu' Daq harm the tera' je the biQ'a',",
        3: "ja'ta', “yImev harm the tera', ghobe' the biQ'a', ghobe' the Sormey, until maH ghaj sealed the bondservants vo' maj joH'a' Daq chaj foreheads!”",
        4: "jIH Qoyta' the mI' vo' chaH 'Iv were sealed, wa' vatlh loSmaH- loS SaD, sealed pa' vo' Hoch tuq vo' the puqpu' vo' Israel:",
        5: "vo' the tuq vo' Judah were sealed cha' wa'maH SaD, vo' the tuq vo' Reuben cha' wa'maH SaD, vo' the tuq vo' Gad cha' wa'maH SaD,",
        6: "vo' the tuq vo' Asher cha' wa'maH SaD, vo' the tuq vo' Naphtali cha' wa'maH SaD, vo' the tuq vo' Manasseh cha' wa'maH SaD,",
        7: "vo' the tuq vo' Simeon cha' wa'maH SaD, vo' the tuq vo' Levi cha' wa'maH SaD, vo' the tuq vo' Issachar cha' wa'maH SaD,",
        8: "vo' the tuq vo' Zebulun cha' wa'maH SaD, vo' the tuq vo' Joseph cha' wa'maH SaD, vo' the tuq vo' Benjamin were sealed cha' wa'maH SaD.",
        9: "After Dochvammey Dochmey jIH nejta', je yIlegh, a Dun qevmey, nuq ghobe' loD laH mI', pa' vo' Hoch Hatlh je vo' Hoch tuqpu', ghotpu', je languages, standing qaSpa' the quS'a' je qaSpa' the Lamb, dressed Daq chIS robes, tlhej palm branches Daq chaj ghopmey.",
        10: "chaH SaQta' tlhej a loud ghogh, ja'ta', “toDtaHghach taH Daq maj joH'a', 'Iv sits Daq the quS'a', je Daq the Lamb!”",
        11: "Hoch the Duy''a'pu' were standing around the quS'a', the quppu', je the loS yIntaH creatures; je chaH pumta' Daq chaj faces qaSpa' Daj quS'a', je worshiped joH'a',",
        12: "ja'ta', “Amen! Blessing, batlh, valtaHghach, tlho'taHghach, quv, HoS, je might, taH Daq maj joH'a' reH je ever! Amen.”",
        13: "wa' vo' the quppu' jangta', ja'ta' Daq jIH, “Dochvammey 'Iv 'oH arrayed Daq chIS robes, 'Iv 'oH chaH, je vo' nuqDaq ta'ta' chaH ghoS?”",
        14: "jIH ja'ta' ghaH, “wIj joH, SoH Sov.” ghaH ja'ta' Daq jIH, “Dochvammey 'oH chaH 'Iv ghoSta' pa' vo' the Dun tribulation. chaH washed chaj robes, je chenmoHta' chaH chIS Daq the Lamb's 'Iw.",
        15: "vaj chaH 'oH qaSpa' the quS'a' vo' joH'a', chaH toy' ghaH jaj je ram Daq Daj lalDan qach. ghaH 'Iv sits Daq the quS'a' DichDaq ngeH Daj tabernacle Dung chaH.",
        16: "chaH DichDaq never taH hungry, ghobe' thirsty vay' latlh; ghobe' DichDaq the pemHov qIp Daq chaH, ghobe' vay' heat;",
        17: "vaD the Lamb 'Iv ghaH Daq the midst vo' the quS'a' shepherds chaH, je Dev chaH Daq springs vo' bIQmey vo' yIn. je joH'a' DichDaq wipe DoH Hoch tear vo' chaj mInDu'.”",
    },
    8: {
        1: "ghorgh ghaH poSmaHpu' the SochDIch seal, pa' ghaHta' tammoH Daq chal vaD about bID an hour.",
        2: "jIH leghta' the Soch Duy''a'pu' 'Iv Qam qaSpa' joH'a', je Soch trumpets were nobpu' Daq chaH.",
        3: "Another Duy ghoSta' je Qampu' Dung the lalDanta' Daq, ghajtaH a golden censer. 'ar He' ghaHta' nobpu' Daq ghaH, vetlh ghaH should chel 'oH Daq the qoy'taHghachmey vo' Hoch the le' ghotpu' Daq the golden lalDanta' Daq nuq ghaHta' qaSpa' the quS'a'.",
        4: "The tlhIch vo' the He', tlhej the qoy'taHghachmey vo' the le' ghotpu', mejta' Dung qaSpa' joH'a' pa' vo' the angel's ghop.",
        5: "The Duy tlhapta' the censer, je ghaH tebta' 'oH tlhej the qul vo' the lalDanta' Daq, je threw 'oH Daq the tera'. pa' tlha'ta' thunders, wabmey, lightnings, je an earthquake.",
        6: "The Soch Duy''a'pu' 'Iv ghajta' the Soch trumpets prepared themselves Daq wab.",
        7: "The wa'Dich ghumta', je pa' tlha'ta' hail je qul, DuD tlhej 'Iw, je chaH were thrown Daq the tera'. wa' wejDIch vo' the tera' ghaHta' meQqu'pu' Dung, { Note: TR omits “wa' wejDIch vo' the tera' ghaHta' meQqu'pu' Dung” } je wa' wejDIch vo' the Sormey were meQqu'pu' Dung, je Hoch SuD grass ghaHta' meQqu'pu' Dung.",
        8: "The cha'DIch Duy ghumta', je something rur a Dun burning HuD ghaHta' thrown Daq the biQ'a'. wa' wejDIch vo' the biQ'a' mojta' 'Iw,",
        9: "je wa' wejDIch vo' the yIntaH creatures nuq were Daq the biQ'a' Heghta'. wa' wejDIch vo' the ships were Qaw'ta'.",
        10: "The wejDIch Duy ghumta', je a Dun Hov pumta' vo' the sky, burning rur a torch, je 'oH pumta' Daq wa' wejDIch vo' the rivers, je Daq the springs vo' the bIQmey.",
        11: "The pong vo' the Hov ghaH ja' “Wormwood.” wa' wejDIch vo' the bIQmey mojta' wormwood. law' ghotpu Heghta' vo' the bIQmey, because chaH were chenmoHta' bitter.",
        12: "The fourth Duy ghumta', je wa' wejDIch vo' the pemHov ghaHta' struck, je wa' wejDIch vo' the maS, je wa' wejDIch vo' the stars; vaj vetlh wa' wejDIch vo' chaH would taH darkened, je the jaj wouldn't shine vaD wa' wejDIch vo' 'oH, je the ram Daq the rap way.",
        13: "jIH leghta', je jIH Qoyta' an eagle, { Note: TR reads “Duy” instead vo' “eagle” } flying Daq mid chal, ja'ta' tlhej a loud ghogh, “Woe! Woe! Woe vaD chaH 'Iv yIn Daq the tera', because vo' the latlh voices vo' the trumpets vo' the wej Duy''a'pu', 'Iv 'oH yet Daq wab!”",
    },
    9: {
        1: "The fifth Duy ghumta', je jIH leghta' a Hov vo' the sky nuq ghajta' fallen Daq the tera'. The key Daq the pit vo' the abyss ghaHta' nobpu' Daq ghaH.",
        2: "ghaH poSmaHpu' the pit vo' the abyss, je tlhIch mejta' Dung pa' vo' the pit, rur the tlhIch vo' a { Note: TR cheltaH “Dun” } burning furnace. The pemHov je the air were darkened because vo' the tlhIch vo' the pit.",
        3: "vaj pa' vo' the tlhIch ghoSta' vo' locusts Daq the tera', je HoS ghaHta' nobpu' Daq chaH, as the scorpions vo' the tera' ghaj HoS.",
        4: "chaH were ja'ta' vetlh chaH should ghobe' hurt the grass vo' the tera', ghobe' vay' SuD Doch, ghobe' vay' Sor, 'ach neH chaH ghotpu 'Iv yImev ghaj joH'a' seal Daq chaj foreheads.",
        5: "chaH were nobpu' HoS ghobe' Daq HoH chaH, 'ach Daq torment chaH vaD vagh months. chaj torment ghaHta' rur the torment vo' a scorpion, ghorgh 'oH strikes a person.",
        6: "Daq chaH jajmey ghotpu DichDaq nej Hegh, je DichDaq Daq ghobe' way tu' 'oH. chaH DichDaq neH Daq Hegh, je Hegh DichDaq Haw' vo' chaH.",
        7: "The shapes vo' the locusts were rur horses prepared vaD veS. Daq chaj nachDu' were something rur golden crowns, je chaj faces were rur people's faces.",
        8: "chaH ghajta' jIb rur women's jIb, je chaj teeth were rur chaH vo' lions.",
        9: "chaH ghajta' breastplates, rur breastplates vo' iron. The wab vo' chaj telDu' ghaHta' rur the wab vo' Dujmey, joq vo' law' horses rushing Daq veS.",
        10: "chaH ghaj tails rur chaH vo' scorpions, je stings. Daq chaj tails chaH ghaj HoS Daq harm loDpu' vaD vagh months.",
        11: "chaH ghaj Dung chaH as joH the Duy vo' the abyss. Daj pong Daq Hebrew ghaH “Abaddon,” { Note: “Abaddon” ghaH a Hebrew mu' vetlh means ruin, QIH, joq the Daq vo' QIH } 'ach Daq Greek, ghaH ghajtaH the pong “Apollyon.” { Note: “Apollyon” means “Destroyer.” }",
        12: "The wa'Dich woe ghaH past. yIlegh, pa' 'oH vIHHa' cha' woes choltaH after vam.",
        13: "The javDich Duy ghumta'. jIH Qoyta' a ghogh vo' the horns vo' the golden lalDanta' Daq nuq ghaH qaSpa' joH'a',",
        14: "ja'ta' Daq the javDich Duy 'Iv ghajta' wa' trumpet, “Free the loS Duy''a'pu' 'Iv 'oH bagh Daq the Dun bIQtIQ Euphrates!”",
        15: "The loS Duy''a'pu' were freed 'Iv ghajta' taH prepared vaD vetlh hour je jaj je jar je DIS, vaj vetlh chaH might HoH wa' wejDIch vo' mankind.",
        16: "The mI' vo' the armies vo' the horsemen ghaHta' cha' vatlh million { Note: literally, “wa'maH SaDmey vo' wa'maH SaDmey” }. jIH Qoyta' the mI' vo' chaH.",
        17: "Thus jIH leghta' the horses Daq the leghtaHghach, je chaH 'Iv ba'ta' Daq chaH, ghajtaH breastplates vo' fiery Doq, hyacinth blue, je sulfur yellow; je the nachDu' vo' lions. pa' vo' chaj mouths proceed qul, tlhIch, je sulfur.",
        18: "Sum Dochvammey wej plagues were wa' wejDIch vo' mankind HoHta': Sum the qul, the tlhIch, je the sulfur, nuq proceeded pa' vo' chaj mouths.",
        19: "vaD the HoS vo' the horses ghaH Daq chaj mouths, je Daq chaj tails. vaD chaj tails 'oH rur serpents, je ghaj nachDu', je tlhej chaH chaH harm.",
        20: "The leS vo' mankind, 'Iv were ghobe' HoHta' tlhej Dochvammey plagues, ta'be' repent vo' the vum vo' chaj ghopmey, vetlh chaH wouldn't lalDan toy' demons, je the idols vo' SuD baS, je vo' baS chIS, je vo' brass, je vo' nagh, je vo' wood; nuq laH ghobe' legh, ghobe' Qoy, ghobe' yIt.",
        21: "chaH ta'be' repent vo' chaj murders, ghobe' vo' chaj sorceries, { Note: The mu' vaD “sorceries” (pharmakeia) je implies the use vo' potions, poisons, je drugs } ghobe' vo' chaj sexual immorality, ghobe' vo' chaj thefts.",
    },
    10: {
        1: "jIH leghta' a HoS Duy choltaH bIng pa' vo' the sky, clothed tlhej a cloud. A rainbow ghaHta' Daq Daj nach. Daj qab ghaHta' rur the pemHov, je Daj qamDu' rur pillars vo' qul.",
        2: "ghaH ghajta' Daq Daj ghop a mach poSmoH paq. ghaH cher Daj nIH qam Daq the biQ'a', je Daj poS Daq the puH.",
        3: "ghaH SaQta' tlhej a loud ghogh, as a HaDI'baH roars. ghorgh ghaH SaQta', the Soch thunders uttered chaj voices.",
        4: "ghorgh the Soch thunders ghumta', jIH ghaHta' about Daq write; 'ach jIH Qoyta' a ghogh vo' the sky ja'ta', “Seal Dung the Dochmey nuq the Soch thunders ja'ta', je yImev write chaH.”",
        5: "The Duy 'Iv jIH leghta' standing Daq the biQ'a' je Daq the puH qengta' Dung Daj nIH ghop Daq the sky,",
        6: "je swore Sum ghaH 'Iv yIn reH je ever, 'Iv created chal je the Dochmey vetlh 'oH Daq 'oH, the tera' je the Dochmey vetlh 'oH Daq 'oH, je the biQ'a' je the Dochmey vetlh 'oH Daq 'oH, vetlh pa' DichDaq ghobe' longer taH delay,",
        7: "'ach Daq the jajmey vo' the ghogh vo' the SochDIch Duy, ghorgh ghaH ghaH about Daq wab, vaj the mystery vo' joH'a' ghaH finished, as ghaH declared Daq Daj toy'wI'pu', the leghwI'pu'.",
        8: "The ghogh nuq jIH Qoyta' vo' chal, again speaking tlhej jIH, ja'ta', “jaH, tlhap the paq nuq ghaH poSmoH Daq the ghop vo' the Duy 'Iv stands Daq the biQ'a' je Daq the puH.”",
        9: "jIH mejta' Daq the Duy, telling ghaH Daq nob jIH the mach paq. ghaH ja'ta' Daq jIH, “tlhap 'oH, je Sop 'oH Dung. 'oH DichDaq chenmoH lIj stomach bitter, 'ach Daq lIj nujDu' 'oH DichDaq taH as sweet as honey.”",
        10: "jIH tlhapta' the mach paq pa' vo' the angel's ghop, je ate 'oH Dung. 'oH ghaHta' as sweet as honey Daq wIj nujDu'. ghorgh jIH ghajta' eaten 'oH, wIj stomach ghaHta' chenmoHta' bitter.",
        11: "chaH ja'ta' jIH, “SoH must prophesy again Dung law' ghotpu', tuqpu', languages, je joHpu'.”",
    },
    11: {
        1: "A reed rur a DevwI' naQ ghaHta' nobpu' Daq jIH. Someone ja'ta', “Hu', je juv joH'a' lalDan qach, je the lalDanta' Daq, je chaH 'Iv lalDan toy' Daq 'oH.",
        2: "mej pa' the bo'DIj nuq ghaH outside vo' the lalDan qach, je yImev juv 'oH, vaD 'oH ghajtaH taH nobpu' Daq the tuqpu'. chaH DichDaq yIt the le' veng bIng qam vaD loSmaH- cha' months.",
        3: "jIH DichDaq nob HoS Daq wIj cha' witnesses, je chaH DichDaq prophesy wa' SaD cha' vatlh javmaH jajmey, clothed Daq sackcloth.”",
        4: "Dochvammey 'oH the cha' olive Sormey je the cha' lampstands, standing qaSpa' the joH vo' the tera'.",
        5: "chugh anyone desires Daq harm chaH, qul proceeds pa' vo' chaj nujDu' je devours chaj jaghpu'. chugh anyone desires Daq harm chaH, ghaH must taH HoHta' Daq vam way.",
        6: "Dochvammey ghaj the HoS Daq shut Dung the sky, vetlh 'oH may ghobe' rain during the jajmey vo' chaj prophecy. chaH ghaj HoS Dung the bIQmey, Daq tlhe' chaH Daq 'Iw, je Daq mup the tera' tlhej Hoch rop'a', as often as chaH neH.",
        7: "ghorgh chaH ghaj finished chaj testimony, the Ha'DIbaH vetlh choltaH Dung pa' vo' the abyss DichDaq chenmoH veS tlhej chaH, je overcome chaH, je HoH chaH.",
        8: "chaj Heghpu' porghmey DichDaq taH Daq the street vo' the Dun veng, nuq spiritually ghaH ja' Sodom je Egypt, nuqDaq je chaj joH ghaHta' crucified.",
        9: "vo' among the ghotpu', tuqpu', languages, je tuqpu' ghotpu DichDaq legh Daq chaj Heghpu' porghmey vaD wej je a bID jajmey, je DichDaq ghobe' allow chaj Heghpu' porghmey Daq taH laid Daq a tomb.",
        10: "chaH 'Iv yIn Daq the tera' yItIv Dung chaH, je chaH DichDaq taH Quchqu'. chaH DichDaq nob gifts Daq wa' another, because Dochvammey cha' leghwI'pu' tormented chaH 'Iv yIn Daq the tera'.",
        11: "After the wej je a bID jajmey, the breath vo' yIn vo' joH'a' 'elta' Daq chaH, je chaH Qampu' Daq chaj qamDu'. Dun taHvIp pumta' Daq chaH 'Iv leghta' chaH.",
        12: "jIH Qoyta' a loud ghogh vo' chal ja'ta' Daq chaH, “ghoS Dung naDev!” chaH mejta' Dung Daq chal Daq the cloud, je chaj jaghpu' leghta' chaH.",
        13: "Daq vetlh jaj pa' ghaHta' a Dun earthquake, je a tenth vo' the veng pumta'. Soch SaD ghotpu were HoHta' Daq the earthquake, je the leS were terrified, je nobta' batlh Daq the joH'a' vo' chal.",
        14: "The cha'DIch woe ghaH past. yIlegh, the wejDIch woe choltaH quickly.",
        15: "The SochDIch Duy ghumta', je Dun voices Daq chal tlha'ta', ja'ta', “The kingdom vo' the qo' ghajtaH moj the Kingdom vo' maj joH, je vo' Daj Christ. ghaH DichDaq che' reH je ever!”",
        16: "The cha'maH- loS quppu', 'Iv ba' Daq chaj thrones qaSpa' joH'a' quS'a', pumta' Daq chaj faces je worshiped joH'a',",
        17: "ja'ta': “maH nob SoH tlho', joH joH'a', the HoSghaj, the wa' 'Iv ghaH je 'Iv ghaHta' { Note: TR cheltaH “je 'Iv ghaH choltaH” }; because SoH ghaj tlhappu' lIj Dun HoS, je che'ta'.",
        18: "The tuqpu' were angry, je lIj QeHpu' ghoSta', as ta'ta' the poH vaD the Heghpu' Daq taH judged, je Daq nob lIj bondservants the leghwI'pu', chaj pop, as QaQ as Daq the le' ghotpu', je chaH 'Iv taHvIp lIj pong, Daq the mach je the Dun; je Daq Qaw' chaH 'Iv Qaw' the tera'.”",
        19: "joH'a' lalDan qach vetlh ghaH Daq chal ghaHta' poSmaHpu', je the Duj vo' the joH lay' ghaHta' leghpu' Daq Daj lalDan qach. Lightnings, wabmey, thunders, an earthquake, je Dun hail tlha'ta'.",
    },
    12: {
        1: "A Dun sign ghaHta' leghpu' Daq chal: a be' clothed tlhej the pemHov, je the maS bIng Daj qamDu', je Daq Daj nach a crown vo' cha' wa'maH stars.",
        2: "ghaH ghaHta' tlhej puq. ghaH SaQta' pa' Daq pain, laboring Daq nob birth.",
        3: "Another sign ghaHta' leghpu' Daq chal. yIlegh, a Dun Doq dragon, ghajtaH Soch nachDu' je wa'maH horns, je Daq Daj nachDu' Soch crowns.",
        4: "Daj tail drew wa' wejDIch vo' the stars vo' the sky, je threw chaH Daq the tera'. The dragon Qampu' qaSpa' the be' 'Iv ghaHta' about Daq nob birth, vaj vetlh ghorgh ghaH nobta' birth ghaH might Sop Daj puq.",
        5: "ghaH nobta' birth Daq a puqloD, a male puq, 'Iv ghaH Daq rule Hoch the tuqpu' tlhej a DevwI' naQ vo' iron. Daj puq ghaHta' caught Dung Daq joH'a', je Daq Daj quS'a'.",
        6: "The be' Haw'ta' Daq the ngem, nuqDaq ghaH ghajtaH a Daq prepared Sum joH'a', vetlh pa' chaH may nourish Daj wa' SaD cha' vatlh javmaH jajmey.",
        7: "pa' ghaHta' veS Daq the sky. Michael je Daj Duy''a'pu' chenmoHta' veS Daq the dragon. The dragon je Daj Duy''a'pu' chenmoHta' veS.",
        8: "chaH ta'be' prevail, ghobe' ghaHta' a Daq tu'ta' vaD ghaH vay' latlh Daq chal.",
        9: "The Dun dragon ghaHta' thrown bIng, the qan lung, ghaH 'Iv ghaH ja' the devil je Satan, the deceiver vo' the Hoch qo'. ghaH ghaHta' thrown bIng Daq the tera', je Daj Duy''a'pu' were thrown bIng tlhej ghaH.",
        10: "jIH Qoyta' a loud ghogh Daq chal, ja'ta', “DaH ghaH ghoS the toDtaHghach, the HoS, je the Kingdom vo' maj joH'a', je the authority vo' Daj Christ; vaD the accuser vo' maj loDnI'pu' ghajtaH taH thrown bIng, 'Iv accuses chaH qaSpa' maj joH'a' jaj je ram.",
        11: "chaH overcame ghaH because vo' the Lamb's 'Iw, je because vo' the mu' vo' chaj testimony. chaH ta'be' muSHa' chaj yIn, 'ach Daq Hegh.",
        12: "vaj yItIv, chal, je SoH 'Iv yIn Daq chaH. Woe Daq the tera' je Daq the biQ'a', because the devil ghajtaH ghoSta' bIng Daq SoH, ghajtaH Dun QeHpu', knowing vetlh ghaH ghajtaH 'ach a short poH.”",
        13: "ghorgh the dragon leghta' vetlh ghaH ghaHta' thrown bIng Daq the tera', ghaH persecuted the be' 'Iv nobta' birth Daq the male puq.",
        14: "cha' telDu' vo' the Dun eagle were nobpu' Daq the taH', vetlh ghaH might puv Daq the ngem Daq Daj Daq, vaj vetlh ghaH might be je'moHta' vaD a poH, je poHmey, je bID a poH, vo' the qab vo' the lung.",
        15: "The lung spewed bIQ pa' vo' Daj nujDu' after the taH' rur a bIQtIQ, vetlh ghaH might cause Daj Daq be qengta' DoH Sum the stream.",
        16: "The tera' helped the be', je the tera' poSmaHpu' its nujDu' je swallowed Dung the bIQtIQ nuq the dragon spewed pa' vo' Daj nujDu'.",
        17: "The dragon grew angry tlhej the be', je mejta' DoH Daq chenmoH veS tlhej the leS vo' Daj tIr, 'Iv pol joH'a' ra'ta'ghach mu'mey je 'uch Jesus' testimony.",
    },
    13: {
        1: "vaj jIH Qampu' Daq the sand vo' the biQ'a'. jIH leghta' a Ha'DIbaH choltaH Dung pa' vo' the biQ'a', ghajtaH wa'maH horns je Soch nachDu'. Daq Daj horns were wa'maH crowns, je Daq Daj nachDu', blasphemous pongmey.",
        2: "The Ha'DIbaH nuq jIH leghta' ghaHta' rur a leopard, je Daj qamDu' were rur chaH vo' a SIQ, je Daj nujDu' rur the nujDu' vo' a HaDI'baH. The dragon nobta' ghaH Daj HoS, Daj quS'a', je Dun authority.",
        3: "wa' vo' Daj nachDu' nejta' rur 'oH ghajta' taH wounded fatally. Daj fatal wound ghaHta' healed, je the Hoch tera' marveled Daq the Ha'DIbaH.",
        4: "chaH worshiped the dragon, because ghaH nobta' Daj authority Daq the Ha'DIbaH, je chaH worshiped the Ha'DIbaH, ja'ta', “'Iv ghaH rur the Ha'DIbaH? 'Iv ghaH laH Daq chenmoH veS tlhej ghaH?”",
        5: "A nujDu' speaking Dun Dochmey je blasphemy ghaHta' nobpu' Daq ghaH. Authority Daq chenmoH veS vaD loSmaH- cha' months ghaHta' nobpu' Daq ghaH.",
        6: "ghaH poSmaHpu' Daj nujDu' vaD blasphemy Daq joH'a', Daq blaspheme Daj pong, je Daj dwelling, chaH 'Iv yIn Daq chal.",
        7: "'oH ghaHta' nobpu' Daq ghaH Daq chenmoH veS tlhej the le' ghotpu', je Daq overcome chaH. Authority Dung Hoch tuq, ghotpu, language, je Hatlh ghaHta' nobpu' Daq ghaH.",
        8: "Hoch 'Iv yIn Daq the tera' DichDaq lalDan toy' ghaH, Hoch 'Iv pong ghajtaH ghobe' taH ghItlhta' vo' the foundation vo' the qo' Daq the paq vo' yIn vo' the Lamb 'Iv ghajtaH taH HoHta'.",
        9: "chugh anyone ghajtaH an qogh, chaw' ghaH Qoy.",
        10: "chugh anyone ghajtaH captivity, ghaH DichDaq jaH Daq captivity. chugh anyone ghaH tlhej the 'etlh, ghaH must taH HoHta'. { Note: TR reads “chugh anyone Dev Daq captivity, Daq captivity ghaH goes. chugh anyone DichDaq HoH tlhej the 'etlh, ghaH must taH HoHta' tlhej a 'etlh.” instead vo' “chugh anyone ghajtaH captivity, ghaH DichDaq jaH Daq captivity. chugh anyone ghaH tlhej the 'etlh, ghaH must taH HoHta'.” } naDev ghaH the endurance je the HartaHghach vo' the le' ghotpu'.",
        11: "jIH leghta' another Ha'DIbaH choltaH Dung pa' vo' the tera'. ghaH ghajta' cha' horns rur a lamb, je ghaH jatlhta' rur a dragon.",
        12: "ghaH exercises Hoch the authority vo' the wa'Dich Ha'DIbaH Daq Daj Daq. ghaH chen the tera' je chaH 'Iv yIn Daq 'oH Daq lalDan toy' the wa'Dich Ha'DIbaH, 'Iv fatal wound ghaHta' healed.",
        13: "ghaH performs Dun signs, 'ach making qul ghoS bIng pa' vo' the sky Daq the tera' Daq the leghpu' vo' ghotpu.",
        14: "ghaH deceives wIj ghaj ghotpu 'Iv yIn Daq the tera' because vo' the signs ghaH ghaHta' granted Daq ta' Daq front vo' the Ha'DIbaH; ja'ta' Daq chaH 'Iv yIn Daq the tera', vetlh chaH should chenmoH an image Daq the Ha'DIbaH 'Iv ghajta' the 'etlh wound je yInta'.",
        15: "'oH ghaHta' nobpu' Daq ghaH Daq nob breath Daq 'oH, Daq the image vo' the Ha'DIbaH, vetlh the image vo' the Ha'DIbaH should both jatlh, je cause as law' as wouldn't lalDan toy' the image vo' the Ha'DIbaH Daq taH HoHta'.",
        16: "ghaH causes Hoch, the mach je the Dun, the rich je the mIpHa', je the free je the toy'wI''a', Daq taH nobpu' marks Daq chaj nIH ghopmey, joq Daq chaj foreheads;",
        17: "je vetlh ghobe' wa' would taH laH Daq buy joq Daq sell, unless ghaH ghajtaH vetlh mark, the pong vo' the Ha'DIbaH joq the mI' vo' Daj pong.",
        18: "naDev ghaH valtaHghach. ghaH 'Iv ghajtaH yajtaHghach, chaw' ghaH calculate the mI' vo' the Ha'DIbaH, vaD 'oH ghaH the mI' vo' a loD. Daj mI' ghaH jav vatlh javmaH- jav.",
    },
    14: {
        1: "jIH leghta', je yIlegh, the Lamb standing Daq Mount Zion, je tlhej ghaH a mI', wa' vatlh loSmaH- loS SaD, ghajtaH Daj pong, je the pong vo' Daj vav, ghItlhta' Daq chaj foreheads.",
        2: "jIH Qoyta' a wab vo' chal, rur the wab vo' law' bIQmey, je rur the wab vo' a Dun thunder. The wab nuq jIH Qoyta' ghaHta' rur vetlh vo' harpists playing Daq chaj harps.",
        3: "chaH bom a chu' bom qaSpa' the quS'a', je qaSpa' the loS yIntaH creatures je the quppu'. ghobe' wa' laH ghoj the bom except the wa' vatlh loSmaH- loS SaD, chaH 'Iv ghajta' taH toDta' pa' vo' the tera'.",
        4: "Dochvammey 'oH chaH 'Iv were ghobe' defiled tlhej be'pu', vaD chaH 'oH virgins. Dochvammey 'oH chaH 'Iv tlha' the Lamb wherever ghaH goes. Dochvammey were toDta' Sum Jesus vo' among loDpu', the wa'Dich fruits Daq joH'a' je Daq the Lamb.",
        5: "Daq chaj nujDu' ghaHta' tu'ta' ghobe' Qot, vaD chaH 'oH blameless. { Note: TR cheltaH “qaSpa' the quS'a' vo' joH'a'” }",
        6: "jIH leghta' an Duy flying Daq mid chal, ghajtaH an eternal QaQ News Daq proclaim Daq chaH 'Iv yIn Daq the tera', je Daq Hoch Hatlh, tuq, language, je ghotpu.",
        7: "ghaH ja'ta' tlhej a loud ghogh, “taHvIp the joH, je nob ghaH batlh; vaD the hour vo' Daj yoj ghajtaH ghoS. lalDan toy' ghaH 'Iv chenmoHta' the chal, the tera', the biQ'a', je the springs vo' bIQmey!”",
        8: "Another, a cha'DIch Duy, tlha'ta', ja'ta', “Babylon the Dun ghajtaH fallen, nuq ghajtaH chenmoHta' Hoch the tuqpu' Daq tlhutlh vo' the HIq vo' the QeHpu' vo' Daj sexual immorality.”",
        9: "Another Duy, a wejDIch, tlha'ta' chaH, ja'ta' tlhej a Dun ghogh, “chugh anyone worships the Ha'DIbaH je Daj image, je receives a mark Daq Daj Quch, joq Daq Daj ghop,",
        10: "ghaH je DichDaq tlhutlh vo' the HIq vo' the QeHpu' vo' joH'a', nuq ghaH prepared unmixed Daq the HIvje' vo' Daj QeH. ghaH DichDaq taH tormented tlhej qul je sulfur Daq the Daq vo' the le' Duy''a'pu', je Daq the Daq vo' the Lamb.",
        11: "The tlhIch vo' chaj torment goes Dung reH je ever. chaH ghaj ghobe' leS jaj je ram, chaH 'Iv lalDan toy' the Ha'DIbaH je Daj image, je 'Iv receives the mark vo' Daj pong.",
        12: "naDev ghaH the patience vo' the le' ghotpu', chaH 'Iv pol the ra'ta'ghach mu'mey vo' joH'a', je the HartaHghach vo' Jesus.”",
        13: "jIH Qoyta' the ghogh vo' chal ja'ta', “Write, ‘ghurtaH 'oH the Heghpu' 'Iv Hegh Daq the joH vo' DaH Daq.'” “HIja',” jatlhtaH the qa', “vetlh chaH may leS vo' chaj labors; vaD chaj vum tlha' tlhej chaH.”",
        14: "jIH nejta', je yIlegh, a chIS cloud; je Daq the cloud wa' sitting rur a puqloD vo' loD, { Note: Daniel 7:13 } ghajtaH Daq Daj nach a golden crown, je Daq Daj ghop a sharp sickle.",
        15: "Another Duy ghoSta' pa' vo' the lalDan qach, crying tlhej a loud ghogh Daq ghaH 'Iv ba'ta' Daq the cloud, “ngeH vo' lIj sickle, je reap; vaD the hour Daq reap ghajtaH ghoS; vaD the harvest vo' the tera' ghaH ripe!”",
        16: "ghaH 'Iv ba'ta' Daq the cloud thrust Daj sickle Daq the tera', je the tera' ghaHta' reaped.",
        17: "Another Duy ghoSta' pa' vo' the lalDan qach nuq ghaH Daq chal. ghaH je ghajta' a sharp sickle.",
        18: "Another Duy ghoSta' pa' vo' the lalDanta' Daq, ghaH 'Iv ghajtaH HoS Dung qul, je ghaH ja' tlhej a Dun ghogh Daq ghaH 'Iv ghajta' the sharp sickle, ja'ta', “ngeH vo' lIj sharp sickle, je tay'moH the clusters vo' the vine vo' the tera', vaD the earth's grapes 'oH fully ripe!”",
        19: "The Duy thrust Daj sickle Daq the tera', je boSta' the vintage vo' the tera', je threw 'oH Daq the Dun winepress vo' the QeHpu' vo' joH'a'.",
        20: "The winepress ghaHta' trodden outside vo' the veng, je 'Iw ghoSta' pa' vo' the winepress, 'ach Daq the bridles vo' the horses, as Hop as wa' SaD jav vatlh stadia. { Note: 1600 stadia = 296 kilometers joq 184 miles }",
    },
    15: {
        1: "jIH leghta' another Dun je marvelous sign Daq the sky: Soch Duy''a'pu' ghajtaH the Soch last plagues, vaD Daq chaH joH'a' QeHpu' ghaH finished.",
        2: "jIH leghta' something rur a biQ'a' vo' glass DuD tlhej qul, je chaH 'Iv overcame the Ha'DIbaH, Daj image, { Note: TR cheltaH “Daj mark,” } je the mI' vo' Daj pong, standing Daq the biQ'a' vo' glass, ghajtaH harps vo' joH'a'.",
        3: "chaH bomta' the bom vo' Moses, the toy'wI' vo' joH'a', je the bom vo' the Lamb, ja'ta', “Dun je marvelous 'oH lIj vum, joH joH'a', the HoSghaj! QaQtaHghach je true 'oH lIj Hemey, SoH joH vo' the tuqpu'.",
        4: "'Iv wouldn't taHvIp SoH, joH, je glorify lIj pong? vaD SoH neH 'oH le'. vaD Hoch the tuqpu' DichDaq ghoS je lalDan toy' qaSpa' SoH. vaD lIj QaQtaHghach ta'mey ghaj taH 'angta'.”",
        5: "After Dochvammey Dochmey jIH nejta', je the lalDan qach vo' the tabernacle vo' the testimony Daq chal ghaHta' poSmaHpu'.",
        6: "The Soch Duy''a'pu' 'Iv ghajta' the Soch plagues ghoSta' pa', clothed tlhej pure, bright linen, je wearing golden sashes around chaj breasts.",
        7: "wa' vo' the loS yIntaH creatures nobta' Daq the Soch Duy''a'pu' Soch golden bowls teblu'ta' vo' the QeHpu' vo' joH'a', 'Iv yIn reH je ever.",
        8: "The lalDan qach ghaHta' tebta' tlhej tlhIch vo' the batlh vo' joH'a', je vo' Daj HoS. ghobe' wa' ghaHta' laH Daq 'el Daq the lalDan qach, until the Soch plagues vo' the Soch Duy''a'pu' would taH finished.",
    },
    16: {
        1: "jIH Qoyta' a loud ghogh pa' vo' the lalDan qach, ja'ta' Daq the Soch Duy''a'pu', “jaH je pour pa' the Soch bowls vo' the QeHpu' vo' joH'a' Daq the tera'!”",
        2: "The wa'Dich mejta', je poured pa' Daj bowl Daq the tera', je 'oH mojta' a harmful je mIghtaHghach 'oy' Daq the ghotpu 'Iv ghajta' the mark vo' the Ha'DIbaH, je 'Iv worshiped Daj image.",
        3: "The cha'DIch Duy poured pa' Daj bowl Daq the biQ'a', je 'oH mojta' 'Iw as vo' a Heghpu' loD. Hoch yIntaH Doch Daq the biQ'a' Heghta'.",
        4: "The wejDIch poured pa' Daj bowl Daq the rivers je springs vo' bIQ, je chaH mojta' 'Iw.",
        5: "jIH Qoyta' the Duy vo' the bIQmey ja'ta', “SoH 'oH QaQtaHghach, 'Iv 'oH je 'Iv were, SoH le' wa', because SoH ghaj judged Dochvammey Dochmey.",
        6: "vaD chaH poured pa' the 'Iw vo' the le' ghotpu' je the leghwI'pu', je SoH ghaj nobpu' chaH 'Iw Daq tlhutlh. chaH deserve vam.”",
        7: "jIH Qoyta' the lalDanta' Daq ja'ta', “HIja', joH joH'a', the HoSghaj, true je QaQtaHghach 'oH lIj judgments.”",
        8: "The fourth poured pa' Daj bowl Daq the pemHov, je 'oH ghaHta' nobpu' Daq ghaH Daq scorch loDpu' tlhej qul.",
        9: "ghotpu were scorched tlhej Dun heat, je ghotpu blasphemed the pong vo' joH'a' 'Iv ghajtaH the HoS Dung Dochvammey plagues. chaH ta'be' repent je nob ghaH batlh.",
        10: "The fifth poured pa' Daj bowl Daq the quS'a' vo' the Ha'DIbaH, je Daj kingdom ghaHta' darkened. chaH gnawed chaj jatmey because vo' the pain,",
        11: "je chaH blasphemed the joH'a' vo' chal because vo' chaj pains je chaj 'oy'mey. chaH ta'be' repent vo' chaj vum.",
        12: "The javDich poured pa' Daj bowl Daq the Dun bIQtIQ, the Euphrates. Its bIQ ghaHta' dried Dung, vetlh the way might taH chenmoHta' ready vaD the joHpu' vetlh ghoS vo' the sunrise.",
        13: "jIH leghta' choltaH pa' vo' the nujDu' vo' the dragon, je pa' vo' the nujDu' vo' the Ha'DIbaH, je pa' vo' the nujDu' vo' the false leghwI'pu', wej Say'Ha' spirits, something rur frogs;",
        14: "vaD chaH 'oH spirits vo' demons, performing signs; nuq jaH vo' Daq the joHpu' vo' the Hoch inhabited tera', Daq tay'moH chaH tay' vaD the veS vo' vetlh Dun jaj vo' joH'a', the HoSghaj.",
        15: "“yIlegh, jIH ghoS rur a thief. ghurtaH ghaH ghaH 'Iv watches, je keeps Daj clothes, vaj vetlh ghaH ta'be' yIt naked, je chaH legh Daj tuH.”",
        16: "ghaH boSta' chaH tay' Daq the Daq nuq ghaH ja' Daq Hebrew, Megiddo.",
        17: "The SochDIch poured pa' Daj bowl Daq the air. A loud ghogh ghoSta' vo' pa' vo' the lalDan qach vo' chal, vo' the quS'a', ja'ta', “'oH ghaH ta'pu'!”",
        18: "pa' were lightnings, wabmey, je thunders; je pa' ghaHta' a Dun earthquake, such as ghaHta' ghobe' since pa' were loDpu' Daq the tera', vaj Dun an earthquake, vaj HoS.",
        19: "The Dun veng ghaHta' divided Daq wej parts, je the vengmey vo' the tuqpu' pumta'. Babylon the Dun ghaHta' remembered Daq the leghpu' vo' joH'a', Daq nob Daq Daj the HIvje' vo' the HIq vo' the fierceness vo' Daj QeHpu'.",
        20: "Hoch island Haw'ta' DoH, je the Hudmey were ghobe' tu'ta'.",
        21: "Dun hailstones, about the weight vo' a talent, { Note: 1 talent ghaH about 34 kilograms joq 75 pounds } ghoSta' bIng pa' vo' the sky Daq ghotpu. ghotpu blasphemed joH'a' because vo' the rop'a' vo' the hail, vaD vam rop'a' ghaH exceedingly severe.",
    },
    17: {
        1: "wa' vo' the Soch Duy''a'pu' 'Iv ghajta' the Soch bowls ghoSta' je jatlhta' tlhej jIH, ja'ta', “ghoS naDev. jIH DichDaq cha' SoH the yoj vo' the Dun naybe'wI' 'Iv sits Daq law' bIQmey,",
        2: "tlhej 'Iv the joHpu' vo' the tera' committed sexual immorality, je chaH 'Iv yIn Daq the tera' were chenmoHta' drunken tlhej the HIq vo' Daj sexual immorality.”",
        3: "ghaH qengta' jIH DoH Daq the qa' Daq a ngem. jIH leghta' a be' sitting Daq a Doq-colored animal, teblu'ta' vo' blasphemous pongmey, ghajtaH Soch nachDu' je wa'maH horns.",
        4: "The be' ghaHta' dressed Daq purple je Doq, je decked tlhej SuD baS je precious naghmey je pearls, ghajtaH Daq Daj ghop a golden HIvje' teblu'ta' vo' qabqu'boghghachmey je the impurities vo' the sexual immorality vo' the tera'.",
        5: "je Daq Daj Quch a pong ghaHta' ghItlhta', “MYSTERY, BABYLON THE Dun, THE SoS vo' THE PROSTITUTES je vo' THE qabqu'boghghachmey vo' THE tera'.”",
        6: "jIH leghta' the be' drunken tlhej the 'Iw vo' the le' ghotpu', je tlhej the 'Iw vo' the martyrs vo' Jesus. ghorgh jIH leghta' Daj, jIH wondered tlhej Dun amazement.",
        7: "The Duy ja'ta' Daq jIH, “qatlh ta' SoH wonder? jIH DichDaq ja' SoH the mystery vo' the be', je vo' the Ha'DIbaH vetlh carries Daj, nuq ghajtaH the Soch nachDu' je the wa'maH horns.",
        8: "The Ha'DIbaH vetlh SoH leghta' ghaHta', je ghaH ghobe'; je ghaH about Daq ghoS Dung pa' vo' the abyss je Daq jaH Daq QIH. chaH 'Iv yIn Daq the tera' je 'Iv pongmey ghaj ghobe' taH ghItlhta' Daq the paq vo' yIn vo' the foundation vo' the qo' DichDaq marvel ghorgh chaH legh vetlh the Ha'DIbaH ghaHta', je ghaH ghobe', je DIchDaq taH present. { Note: TR reads “yet ghaH” instead vo' “DIchDaq taH present” }",
        9: "naDev ghaH the yab vetlh ghajtaH valtaHghach. The Soch nachDu' 'oH Soch Hudmey, Daq nuq the be' sits.",
        10: "chaH 'oH Soch joHpu'. vagh ghaj fallen, the wa' ghaH, the latlh ghajtaH ghobe' yet ghoS. ghorgh ghaH choltaH, ghaH must continue a mach qaStaHvIS.",
        11: "The Ha'DIbaH vetlh ghaHta', je ghaH ghobe', ghaH himself je an eighth, je ghaH vo' the Soch; je ghaH goes Daq QIH.",
        12: "The wa'maH horns vetlh SoH leghta' 'oH wa'maH joHpu' 'Iv ghaj Hevta' ghobe' kingdom as yet, 'ach chaH Hev authority as joHpu', tlhej the Ha'DIbaH, vaD wa' hour.",
        13: "Dochvammey ghaj wa' yab, je chaH nob chaj HoS je authority Daq the Ha'DIbaH.",
        14: "Dochvammey DichDaq veS Daq the Lamb, je the Lamb DichDaq overcome chaH, vaD ghaH ghaH joH vo' lords, je joH vo' joHpu'. chaH je DichDaq overcome 'Iv 'oH tlhej ghaH, ja' je wIvpu' je voqmoH.”",
        15: "ghaH ja'ta' Daq jIH, “The bIQmey nuq SoH leghta', nuqDaq the naybe'wI' sits, 'oH ghotpu', multitudes, tuqpu', je languages.",
        16: "The wa'maH horns nuq SoH leghta', je the Ha'DIbaH, Dochvammey DichDaq hate the naybe'wI', je DichDaq chenmoH Daj moB, je DichDaq chenmoH Daj naked, je DichDaq Sop Daj ghab, je DichDaq meQ Daj utterly tlhej qul.",
        17: "vaD joH'a' ghajtaH lan Daq chaj tIQDu' Daq ta' nuq ghaH ghajtaH Daq yab, je Daq taH vo' wa' yab, je Daq nob chaj kingdom Daq the Ha'DIbaH, until the mu'mey vo' joH'a' should taH accomplished.",
        18: "The be' 'Iv SoH leghta' ghaH the Dun veng, nuq reigns Dung the joHpu' vo' the tera'.”",
    },
    18: {
        1: "After Dochvammey Dochmey, jIH leghta' another Duy choltaH bIng pa' vo' the sky, ghajtaH Dun authority. The tera' ghaHta' illuminated tlhej Daj batlh.",
        2: "ghaH SaQta' tlhej a HoS ghogh, ja'ta', “Fallen, fallen ghaH Babylon the Dun, je ghaH ghajtaH moj a juH vo' demons, a prison vo' Hoch Say'Ha' qa', je a prison vo' Hoch Say'Ha' je hateful toQ!",
        3: "vaD Hoch the tuqpu' ghaj drunk vo' the HIq vo' the QeHpu' vo' Daj sexual immorality, the joHpu' vo' the tera' committed sexual immorality tlhej Daj, je the merchants vo' the tera' grew rich vo' the abundance vo' Daj luxury.”",
        4: "jIH Qoyta' another ghogh vo' chal, ja'ta', “ghoS pa' vo' Daj, wIj ghotpu, vetlh SoH ghaj ghobe' participation Daq Daj yemmey, je vetlh SoH yImev Hev vo' Daj plagues,",
        5: "vaD Daj yemmey ghaj reached Daq the sky, je joH'a' ghajtaH remembered Daj iniquities.",
        6: "chegh Daq Daj just as ghaH cheghta', je repay Daj double as ghaH ta'ta', je according Daq Daj vum. Daq the HIvje' nuq ghaH DuD, mix Daq Daj double.",
        7: "However 'ar ghaH glorified herself, je grew wanton, vaj 'ar nob Daj vo' torment je mourning. vaD ghaH jatlhtaH Daq Daj tIq, ‘jIH ba' a queen, je 'oH ghobe' Heghbe'nal, je DichDaq Daq ghobe' way legh mourning.'",
        8: "vaj Daq wa' jaj Daj plagues DichDaq ghoS: Hegh, mourning, je famine; je ghaH DichDaq taH utterly meQpu' tlhej qul; vaD the joH joH'a' 'Iv ghajtaH judged Daj ghaH HoS.",
        9: "The joHpu' vo' the tera', 'Iv committed sexual immorality je yInta' wantonly tlhej Daj, DichDaq weep je wail Dung Daj, ghorgh chaH legh Daq the tlhIch vo' Daj burning,",
        10: "standing Hop DoH vaD the taHvIp vo' Daj torment, ja'ta', ‘Woe, woe, the Dun veng, Babylon, the HoS veng! vaD lIj yoj ghajtaH ghoS Daq wa' hour.'",
        11: "The merchants vo' the tera' weep je mourn Dung Daj, vaD ghobe' wa' buys chaj merchandise vay' latlh;",
        12: "merchandise vo' SuD baS, baS chIS, precious naghmey, pearls, fine linen, purple, silk, Doq, Hoch expensive wood, Hoch vessel vo' ivory, Hoch vessel chenmoHta' vo' HochHom precious wood, je vo' brass, je iron, je marble;",
        13: "je cinnamon, He', perfume, frankincense, HIq, olive Hergh, fine flour, wheat, Suy', horses, Dujmey, je people's porghmey je qa'pu'.",
        14: "The fruits nuq lIj qa' lusted after ghaj taH lost Daq SoH, je Hoch Dochmey vetlh were dainty je sumptuous ghaj perished vo' SoH, je SoH DichDaq tu' chaH ghobe' latlh Daq Hoch.",
        15: "The merchants vo' Dochvammey Dochmey, 'Iv were chenmoHta' rich Sum Daj, DichDaq Qam Hop DoH vaD the taHvIp vo' Daj torment, weeping je mourning;",
        16: "ja'ta', ‘Woe, woe, the Dun veng, ghaH 'Iv ghaHta' dressed Daq fine linen, purple, je Doq, je decked tlhej SuD baS je precious naghmey je pearls!",
        17: "vaD Daq an hour such Dun riches 'oH chenmoHta' moB.' Hoch shipmaster, je Hoch 'Iv sails anywhere, je mariners, je as law' as gain chaj yIntaH Sum biQ'a', Qampu' Hop DoH,",
        18: "je SaQta' pa' as chaH nejta' Daq the tlhIch vo' Daj burning, ja'ta', ‘nuq ghaH rur the Dun veng?'",
        19: "chaH chuH dust Daq chaj nachDu', je SaQta', weeping je mourning, ja'ta', ‘Woe, woe, the Dun veng, Daq nuq Hoch 'Iv ghajta' chaj ships Daq the biQ'a' were chenmoHta' rich Sum meq vo' Daj Dun wealth!' vaD Daq wa' hour ghaH ghaH chenmoHta' moB.",
        20: "“yItIv Dung Daj, toH chal, SoH le' ghotpu', apostles, je leghwI'pu'; vaD joH'a' ghajtaH judged lIj yoj Daq Daj.”",
        21: "A HoS Duy tlhapta' Dung a nagh rur a Dun millstone je chuH 'oH Daq the biQ'a', ja'ta', “Thus tlhej violence DichDaq Babylon, the Dun veng, taH thrown bIng, je DichDaq taH tu'ta' ghobe' latlh Daq Hoch.",
        22: "The ghogh vo' harpists, minstrels, flute players, je trumpeters DichDaq taH Qoyta' ghobe' latlh Daq Hoch Daq SoH. ghobe' craftsman, vo' whatever craft, DichDaq taH tu'ta' vay' latlh Daq Hoch Daq SoH. The wab vo' a mill DichDaq taH Qoyta' ghobe' latlh Daq Hoch Daq SoH.",
        23: "The wov vo' a lamp DichDaq shine ghobe' latlh Daq Hoch Daq SoH. The ghogh vo' the bridegroom je vo' the bride DichDaq taH Qoyta' ghobe' latlh Daq Hoch Daq SoH; vaD lIj merchants were the joHHom vo' the tera'; vaD tlhej lIj sorcery Hoch the tuqpu' were deceived.",
        24: "Daq Daj ghaHta' tu'ta' the 'Iw vo' leghwI'pu' je vo' le' ghotpu', je vo' Hoch 'Iv ghaj taH Heghta' Daq the tera'.”",
    },
    19: {
        1: "After Dochvammey Dochmey jIH Qoyta' something rur a loud ghogh vo' a Dun qevmey Daq chal, ja'ta', “Hallelujah! toDtaHghach, HoS, je batlh belong Daq maj joH'a':",
        2: "vaD true je QaQtaHghach 'oH Daj judgments. vaD ghaH ghajtaH judged the Dun naybe'wI', 'Iv corrupted the tera' tlhej Daj sexual immorality, je ghaH ghajtaH avenged the 'Iw vo' Daj toy'wI'pu' Daq Daj ghop.”",
        3: "A cha'DIch ja'ta', “Hallelujah! Daj tlhIch goes Dung reH je ever.”",
        4: "The cha'maH- loS quppu' je the loS yIntaH creatures pumta' bIng je worshiped joH'a' 'Iv sits Daq the quS'a', ja'ta', “Amen! Hallelujah!”",
        5: "A ghogh ghoSta' vo' vo' the quS'a', ja'ta', “nob naD Daq maj joH'a', Hoch SoH Daj toy'wI'pu', SoH 'Iv taHvIp ghaH, the mach je the Dun!”",
        6: "jIH Qoyta' something rur the ghogh vo' a Dun qevmey, je rur the ghogh vo' law' bIQmey, je rur the ghogh vo' HoS thunders, ja'ta', “Hallelujah! vaD the joH maj joH'a', the HoSghaj, reigns!",
        7: "chaw' maH yItIv je taH exceedingly Quchqu', je chaw' maH nob the batlh Daq ghaH. vaD the marriage vo' the Lamb ghajtaH ghoS, je Daj be'nal ghajtaH chenmoHta' herself ready.”",
        8: "'oH ghaHta' nobpu' Daq Daj vetlh ghaH would array herself Daq bright, pure, fine linen: vaD the fine linen ghaH the QaQtaHghach ta'mey vo' the le' ghotpu'.",
        9: "ghaH ja'ta' Daq jIH, “Write, ‘ghurtaH 'oH chaH 'Iv 'oH invited Daq the marriage supper vo' the Lamb.'” ghaH ja'ta' Daq jIH, “Dochvammey 'oH true mu'mey vo' joH'a'.”",
        10: "jIH pumta' bIng qaSpa' Daj qamDu' Daq lalDan toy' ghaH. ghaH ja'ta' Daq jIH, “legh! yImev ta' 'oH! jIH 'oH a fellow bondservant tlhej SoH je tlhej lIj loDnI'pu' 'Iv 'uch the testimony vo' Jesus. lalDan toy' joH'a', vaD the testimony vo' Jesus ghaH the qa' vo' Prophecy.”",
        11: "jIH leghta' the chal poSmaHpu', je yIlegh, a chIS horse, je ghaH 'Iv ba'ta' Daq 'oH ghaH ja' voqmoH je True. Daq QaQtaHghach ghaH judges je chen veS.",
        12: "Daj mInDu' 'oH a flame vo' qul, je Daq Daj nach 'oH law' crowns. ghaH ghajtaH pongmey ghItlhta' je a pong ghItlhta' nuq ghobe' wa' SovtaH 'ach ghaH himself.",
        13: "ghaH ghaH clothed Daq a garment sprinkled tlhej 'Iw. Daj pong ghaH ja' “The mu' vo' joH'a'.”",
        14: "The armies nuq 'oH Daq chal tlha'ta' ghaH Daq chIS horses, clothed Daq chIS, pure, fine linen.",
        15: "pa' vo' Daj nujDu' proceeds a sharp, double-edged 'etlh, vetlh tlhej 'oH ghaH should mup the tuqpu'. ghaH DichDaq rule chaH tlhej an iron DevwI' naQ. { Note: bom 2:9 } ghaH treads the winepress vo' the fierceness vo' the QeHpu' vo' joH'a', the HoSghaj.",
        16: "ghaH ghajtaH Daq Daj garment je Daq Daj thigh a pong ghItlhta', “joH vo' joHpu', je joH vo' LORDS.”",
        17: "jIH leghta' an Duy standing Daq the pemHov. ghaH SaQta' tlhej a loud ghogh, ja'ta' Daq Hoch the toQmey vetlh puv Daq the sky, “ghoS! taH boSta' tay' Daq the Dun supper vo' joH'a', { Note: TR reads “supper vo' the Dun joH'a'” instead vo' “Dun supper vo' joH'a'” }",
        18: "vetlh SoH may Sop the ghab vo' joHpu', the ghab vo' HoDpu', the ghab vo' HoS loDpu', je the ghab vo' horses je vo' chaH 'Iv ba' Daq chaH, je the ghab vo' Hoch loDpu', both free je toy'wI''a', je mach je Dun.”",
        19: "jIH leghta' the Ha'DIbaH, je the joHpu' vo' the tera', je chaj armies, boSta' tay' Daq chenmoH veS Daq ghaH 'Iv ba'ta' Daq the horse, je Daq Daj army.",
        20: "The Ha'DIbaH ghaHta' tlhappu', je tlhej ghaH the false leghwI'pu' 'Iv worked the signs Daq Daj leghpu', tlhej nuq ghaH deceived chaH 'Iv ghajta' Hevta' the mark vo' the Ha'DIbaH je chaH 'Iv worshiped Daj image. Dochvammey cha' were thrown yIn Daq the lake vo' qul vetlh burns tlhej sulfur.",
        21: "The leS were HoHta' tlhej the 'etlh vo' ghaH 'Iv ba'ta' Daq the horse, the 'etlh nuq ghoSta' vo' pa' vo' Daj nujDu'. Hoch the toQmey were tebta' tlhej chaj ghab.",
    },
    20: {
        1: "jIH leghta' an Duy choltaH bIng pa' vo' chal, ghajtaH the key vo' the abyss je a Dun chain Daq Daj ghop.",
        2: "ghaH seized the dragon, the qan lung, nuq ghaH the devil je Satan, 'Iv deceives the Hoch inhabited tera', je bagh ghaH vaD a SaD DISmey,",
        3: "je chuH ghaH Daq the abyss, je shut 'oH, je sealed 'oH Dung ghaH, vetlh ghaH should deceive the tuqpu' ghobe' latlh, until the SaD DISmey were finished. After vam, ghaH must taH freed vaD a short poH.",
        4: "jIH leghta' thrones, je chaH ba'ta' Daq chaH, je yoj ghaHta' nobpu' Daq chaH. jIH leghta' the qa'pu' vo' chaH 'Iv ghajta' taH beheaded vaD the testimony vo' Jesus, je vaD the mu' vo' joH'a', je such as ta'be' lalDan toy' the Ha'DIbaH ghobe' Daj image, je ta'be' Hev the mark Daq chaj Quch je Daq chaj ghop. chaH yInta', je che'ta' tlhej Christ vaD a SaD DISmey.",
        5: "The leS vo' the Heghpu' ta'be' yIn until the SaD DISmey were finished. vam ghaH the wa'Dich resurrection.",
        6: "ghurtaH je le' ghaH ghaH 'Iv ghajtaH part Daq the wa'Dich resurrection. Dung Dochvammey, the cha'DIch Hegh ghajtaH ghobe' HoS, 'ach chaH DichDaq taH lalDan vumwI'pu' vo' joH'a' je vo' Christ, je DichDaq che' tlhej ghaH wa' SaD DISmey.",
        7: "je after the SaD DISmey, Satan DichDaq taH released vo' Daj prison,",
        8: "je ghaH DichDaq ghoS pa' Daq deceive the tuqpu' nuq 'oH Daq the loS corners vo' the tera', Gog je Magog, Daq tay'moH chaH tay' Daq the veS; the mI' vo' 'Iv ghaH as the sand vo' the biQ'a'.",
        9: "chaH mejta' Dung Dung the breadth vo' the tera', je surrounded the raQ vo' the le' ghotpu', je the parmaqqay veng. qul ghoSta' bIng pa' vo' chal vo' joH'a', je Soppu' chaH.",
        10: "The devil 'Iv deceived chaH ghaHta' thrown Daq the lake vo' qul je sulfur, nuqDaq the Ha'DIbaH je the false leghwI'pu' 'oH je. chaH DichDaq taH tormented jaj je ram reH je ever.",
        11: "jIH leghta' a Dun chIS quS'a', je ghaH 'Iv ba'ta' Daq 'oH, vo' 'Iv qab the tera' je the chal Haw'ta' DoH. pa' ghaHta' tu'ta' ghobe' Daq vaD chaH.",
        12: "jIH leghta' the Heghpu', the Dun je the mach, standing qaSpa' the quS'a', je chaH poSmaHpu' paqmey. Another paq ghaHta' poSmaHpu', nuq ghaH the paq vo' yIn. The Heghpu' were judged pa' vo' the Dochmey nuq were ghItlhta' Daq the paqmey, according Daq chaj vum.",
        13: "The biQ'a' nobta' Dung the Heghpu' 'Iv were Daq 'oH. Hegh je Hades { Note: joq, Hell } nobta' Dung the Heghpu' 'Iv were Daq chaH. chaH were judged, each wa' according Daq Daj vum.",
        14: "Hegh je Hades { Note: joq, Hell } were thrown Daq the lake vo' qul. vam ghaH the cha'DIch Hegh, the lake vo' qul.",
        15: "chugh anyone ghaHta' ghobe' tu'ta' ghItlhta' Daq the paq vo' yIn, ghaH ghaHta' chuH Daq the lake vo' qul.",
    },
    21: {
        1: "jIH leghta' a chu' chal je a chu' tera': vaD the wa'Dich chal je the wa'Dich tera' ghaj juSta' DoH, je the biQ'a' ghaH ghobe' latlh.",
        2: "jIH leghta' the le' veng, chu' Jerusalem, choltaH bIng pa' vo' chal vo' joH'a', chenmoHta' ready rur a bride adorned vaD Daj loDnal.",
        3: "jIH Qoyta' a loud ghogh pa' vo' chal ja'ta', “yIlegh, joH'a' dwelling ghaH tlhej ghotpu, je ghaH DichDaq yIn tlhej chaH, je chaH DichDaq taH Daj ghotpu, je joH'a' himself DichDaq taH tlhej chaH as chaj joH'a'.",
        4: "ghaH DichDaq wipe DoH vo' chaH Hoch tear vo' chaj mInDu'. Hegh DichDaq taH ghobe' latlh; ghobe' DichDaq pa' taH mourning, ghobe' crying, ghobe' pain, vay' latlh. The wa'Dich Dochmey ghaj juSta' DoH.”",
        5: "ghaH 'Iv sits Daq the quS'a' ja'ta', “yIlegh, jIH 'oH making Hoch Dochmey chu'.” ghaH ja'ta', “Write, vaD Dochvammey mu'mey vo' joH'a' 'oH voqmoH je true.”",
        6: "ghaH ja'ta' Daq jIH, “'oH ghaH ta'pu'! jIH 'oH the Alpha je the Omega, the tagh je the pItlh. jIH DichDaq nob freely Daq ghaH 'Iv ghaH thirsty vo' the spring vo' the bIQ vo' yIn.",
        7: "ghaH 'Iv overcomes, jIH DichDaq nob ghaH Dochvammey Dochmey. jIH DichDaq taH Daj joH'a', je ghaH DichDaq taH wIj puqloD.",
        8: "'ach vaD the cowardly, unbelieving, yemwI'pu', abominable, chotwI'pu', sexually immoral, sorcerers, { Note: The mu' vaD “sorcerers” naDev je includes users vo' potions je drugs. } idolaters, je Hoch liars, chaj part ghaH Daq the lake vetlh burns tlhej qul je sulfur, nuq ghaH the cha'DIch Hegh.”",
        9: "wa' vo' the Soch Duy''a'pu' 'Iv ghajta' the Soch bowls, 'Iv were loaded tlhej the Soch last plagues ghoSta', je ghaH jatlhta' tlhej jIH, ja'ta', “ghoS naDev. jIH DichDaq cha' SoH the be'nal, the Lamb's bride.”",
        10: "ghaH qengta' jIH DoH Daq the qa' Daq a Dun je jen HuD, je showed jIH the le' veng, Jerusalem, choltaH bIng pa' vo' chal vo' joH'a',",
        11: "ghajtaH the batlh vo' joH'a'. Daj wov ghaHta' rur a HochHom precious nagh, as chugh 'oH ghaHta' a jasper nagh, clear as crystal;",
        12: "ghajtaH a Dun je jen reD; ghajtaH cha' wa'maH lojmItmey, je Daq the lojmItmey cha' wa'maH Duy''a'pu'; je pongmey ghItlhta' Daq chaH, nuq 'oH the pongmey vo' the cha' wa'maH tuqpu' vo' the puqpu' vo' Israel.",
        13: "Daq the pemHov 'o' were wej lojmItmey; je Daq the pemHov nIH wej lojmItmey; je Daq the pemHov poS wej lojmItmey; je Daq the pemHov 'et wej lojmItmey.",
        14: "The reD vo' the veng ghajta' cha' wa'maH foundations, je Daq chaH cha' wa'maH pongmey vo' the cha' wa'maH Apostles vo' the Lamb.",
        15: "ghaH 'Iv jatlhta' tlhej jIH ghajta' vaD a juv, a golden reed, Daq juv the veng, its lojmItmey, je its walls.",
        16: "The veng lies foursquare, je its length ghaH as Dun as its breadth. ghaH juvta' the veng tlhej the reed, cha' wa'maH SaD cha' wa'maH stadia { Note: 12,012 stadia = joq 2,221 kilometers joq 1,380 miles. TR reads 12,000 stadia instead vo' 12,012 stadia. }. Its length, breadth, je height 'oH equal.",
        17: "Its reD ghaH wa' vatlh loSmaH- loS cubits, { Note: 144 cubits ghaH about 65.8 meters joq 216 qamDu' } Sum the juv vo' a loD, vetlh ghaH, vo' an Duy.",
        18: "The construction vo' its reD ghaHta' jasper. The veng ghaHta' pure SuD baS, rur pure glass.",
        19: "The foundations vo' the city's reD were adorned tlhej Hoch kinds vo' precious naghmey. The wa'Dich foundation ghaHta' jasper; the cha'DIch, sapphire { Note: joq, lapis lazuli }; the wejDIch, chalcedony; the fourth, emerald;",
        20: 'the fifth, sardonyx; the javDich, sardius; the SochDIch, chrysolite; the eighth, beryl; the ninth, topaz; the tenth, chrysoprasus; the eleventh, jacinth; je the twelfth, amethyst.',
        21: "The cha' wa'maH lojmItmey were cha' wa'maH pearls. Each wa' vo' the lojmItmey ghaHta' chenmoHta' vo' wa' pearl. The street vo' the veng ghaHta' pure SuD baS, rur transparent glass.",
        22: "jIH leghta' ghobe' lalDan qach Daq 'oH, vaD the joH joH'a', the HoSghaj, je the Lamb, 'oH its lalDan qach.",
        23: "The veng ghajtaH ghobe' need vaD the pemHov, ghobe' vo' the maS, Daq shine, vaD the very batlh vo' joH'a' illuminated 'oH, je its lamp ghaH the Lamb.",
        24: "The tuqpu' DichDaq yIt Daq its wov. The joHpu' vo' the tera' qem the batlh je quv vo' the tuqpu' Daq 'oH.",
        25: "Its lojmItmey DichDaq Daq ghobe' way taH shut Sum jaj (vaD pa' DichDaq taH ghobe' ram pa'),",
        26: "je chaH DIchDaq qem the batlh je the quv vo' the tuqpu' Daq 'oH vaj vetlh chaH may 'el.",
        27: "pa' DichDaq Daq ghobe' way 'el Daq 'oH vay' profane, joq wa' 'Iv causes an qabqu'boghghach joq a Qot, 'ach neH chaH 'Iv 'oH ghItlhta' Daq the Lamb's paq vo' yIn.",
    },
    22: {
        1: "ghaH showed jIH a { Note: TR cheltaH “pure” } bIQtIQ vo' bIQ vo' yIn, clear as crystal, proceeding pa' vo' the quS'a' vo' joH'a' je vo' the Lamb,",
        2: "Daq the middle vo' its street. Daq vam retlh vo' the bIQtIQ je Daq vetlh ghaHta' the Sor vo' yIn, qeng cha' wa'maH kinds vo' fruits, yielding its baQ Hoch jar. The leaves vo' the Sor were vaD the healing vo' the tuqpu'.",
        3: "pa' DichDaq taH ghobe' mu'qaD vay' latlh. The quS'a' vo' joH'a' je vo' the Lamb DichDaq taH Daq 'oH, je Daj toy'wI'pu' toy' ghaH.",
        4: 'chaH DichDaq legh Daj qab, je Daj pong DichDaq taH Daq chaj foreheads.',
        5: "pa' DichDaq taH ghobe' ram, je chaH need ghobe' lamp wov; vaD the joH joH'a' DichDaq illuminate chaH. chaH DichDaq che' reH je ever.",
        6: "ghaH ja'ta' Daq jIH, “Dochvammey mu'mey 'oH voqmoH je true. The joH joH'a' vo' the spirits vo' the leghwI'pu' ngeHta' Daj Duy Daq cha' Daq Daj bondservants the Dochmey nuq must qaS soon.”",
        7: "“yIlegh, jIH ghoS quickly. ghurtaH ghaH ghaH 'Iv keeps the mu'mey vo' the prophecy vo' vam paq.”",
        8: "DaH jIH, John, 'oH the wa' 'Iv Qoyta' je leghta' Dochvammey Dochmey. ghorgh jIH Qoyta' je leghta', jIH pumta' bIng Daq lalDan toy' qaSpa' the qamDu' vo' the Duy 'Iv ghajta' shown jIH Dochvammey Dochmey.",
        9: "ghaH ja'ta' Daq jIH, “legh SoH yImev ta' 'oH! jIH 'oH a fellow bondservant tlhej SoH je tlhej lIj loDnI'pu', the leghwI'pu', je tlhej chaH 'Iv pol the mu'mey vo' vam paq. lalDan toy' joH'a'.”",
        10: "ghaH ja'ta' Daq jIH, “yImev seal Dung the mu'mey vo' the prophecy vo' vam paq, vaD the poH ghaH Daq ghop.",
        11: "ghaH 'Iv ta'mey unjustly, chaw' ghaH vang unjustly vIHHa'. ghaH 'Iv ghaH filthy, chaw' ghaH taH filthy vIHHa'. ghaH 'Iv ghaH QaQtaHghach, chaw' ghaH ta' QaQtaHghach vIHHa'. ghaH 'Iv ghaH le', chaw' ghaH taH le' vIHHa'.”",
        12: '“yIlegh, jIH ghoS quickly. wIj pop ghaH tlhej jIH, Daq repay Daq each loD according Daq Daj vum.',
        13: "jIH 'oH the Alpha je the Omega, the wa'Dich je the Last, the tagh je the pItlh.",
        14: "ghurtaH 'oH chaH 'Iv ta' Daj ra'ta'ghach mu'mey, { Note: NU reads “Seng chaj robes” instead vo' “ta' Daj ra'ta'ghach mu'mey”. } vetlh chaH may ghaj the nIH Daq the Sor vo' yIn, je may 'el Daq Sum the lojmItmey Daq the veng.",
        15: "Outside 'oH the dogs, the sorcerers, the sexually immoral, the chotwI'pu', the idolaters, je Hoch 'Iv muSHa'taH je practices falsehood.",
        16: "jIH, Jesus, ghaj ngeHta' wIj Duy Daq testify Dochvammey Dochmey Daq SoH vaD the yejmey. jIH 'oH the root je the offspring vo' David; the Bright je po Hov.”",
        17: "The qa' je the bride jatlh, “ghoS!” ghaH 'Iv hears, chaw' ghaH jatlh, “ghoS!” ghaH 'Iv ghaH thirsty, chaw' ghaH ghoS. ghaH 'Iv desires, chaw' ghaH tlhap the bIQ vo' yIn freely.",
        18: "jIH testify Daq Hoch 'Iv hears the mu'mey vo' the prophecy vo' vam paq, chugh anyone cheltaH Daq chaH, may joH'a' chel Daq ghaH the plagues nuq 'oH ghItlhta' Daq vam paq.",
        19: "chugh anyone takes DoH vo' the mu'mey vo' the paq vo' vam prophecy, may joH'a' tlhap DoH Daj part vo' the Sor vo' yIn, je pa' vo' the le' veng, nuq 'oH ghItlhta' Daq vam paq.",
        20: "ghaH 'Iv testifies Dochvammey Dochmey jatlhtaH, “HIja', jIH ghoS quickly.” Amen! HIja', ghoS, joH Jesus.",
        21: "The grace vo' the joH Jesus Christ taH tlhej Hoch the le' ghotpu'. Amen.",
    },
}
